"use client";
/* eslint-disable @typescript-eslint/no-explicit-any, react-hooks/use-memo */
import {useEffect,useMemo,useRef,useState} from 'react';
import {ArrowRight,ArrowUpRight,Activity,Building2,ChartNoAxesCombined,Check,ChevronDown,Database,Download,Factory,Layers3,MapPin,RefreshCw,Server,ShieldCheck,TriangleAlert,Zap} from 'lucide-react';
import {ResponsiveContainer,ComposedChart,Line,Bar,XAxis,YAxis,CartesianGrid,Tooltip,Brush,ReferenceLine} from 'recharts';
import type {IndustryDataset,IndustryResearch,MetricDefinition,MetricSeries,Recommendation,ResearchEvidenceReference,ResearchSectorSignal} from '@/lib/industry/types';
