const tabs=[['overview','产业总览'],['metrics','指标看板'],['companies','公司对比'],['conclusions','投资结论'],['sources','数据说明']];
const categories=[['capex','云厂商资本开支'],['cloud','云业务需求'],['projects','数据中心建设'],['power','电力与基础设施'],['servers','服务器与网络设备'],['semiconductor','半导体需求'],['costs','上游成本']];
const labels:Record<string,string>={reported:'已披露',calculated:'已计算',guidance:'公司指引',official:'官方数据',project_announcement:'公告数据',third_party:'第三方估计',proxy:'代理指标',demo:'演示数据'};
const statusLabels:Record<string,string>={ready:'最近抓取成功',reviewed:'官方核验导入',cached:'展示缓存',fetch_failed:'获取失败',pending:'待接入',not_configured:'未配置来源',authorization_required:'待授权数据源',no_observation:'暂无已发布观测'};
const statusText=(series?:MetricSeries)=>series?.status==='cached'&&series.error?'获取失败 · 展示缓存':statusLabels[series?.status??'pending'];
const freq:Record<string,string>={daily:'日度',monthly:'月度',quarterly:'季度',annual:'年度',event:'事件'};
const color=['#167c68','#5b80b2','#c39848','#9e7cb0','#d38067','#6b9b9d'];
const companyColors:Record<string,string>={MSFT:'#167c68',GOOG:'#5b80b2',META:'#c39848',AMZN:'#9e7cb0',ORCL:'#d38067'};
const companyColor=(entity:string)=>companyColors[entity]??color[[...entity].reduce((sum,char)=>(sum*31+char.charCodeAt(0))>>>0,0)%color.length];
const empty:IndustryDataset={schemaVersion:'1',generatedAt:'',definitions:[],series:{},projects:[],events:[]};
const pct=(v:number|null|undefined,unit='%')=>v==null?'—':`${v>0?'↑ ':v<0?'↓ ':'→ '}${format(Math.abs(v))}${unit}`;
const displayTime=(value:string|null|undefined)=>value&&value.length===10?value+'（来源仅记录日期）':beijing(value);
const conf=(v:string)=>({high:'高',medium:'中',low:'低'}[v]??v);
const signedScore=(value:number|null|undefined)=>value==null?'正式待验证':`${value>0?'+':''}${value}`;
const scoringGateLabel=(value:string|undefined)=>({passed:'已通过直接证据门槛',blocked_by_evidence:'正式评分待验证：关键证据不足',blocked_by_history:'正式评分待验证：连续历史不足',blocked_by_directness:'正式评分待验证：仅有代理、项目样本或间接口径'}[value??'']??'正式评分待验证');
const calibrationLabel=(value:string|undefined)=>({history_normalized:'历史标准化通过',calibrated:'历史标准化通过',early_signal:'含早期方向信号',not_scored:'未形成可评分历史'}[value??'']??'未形成可评分历史');
const hasLeadingSignal=(signal:ResearchSectorSignal|null|undefined)=>{const leading=signal?.leadingSignal;return signal?.score==null&&leading?.status==='available'&&leading.score!=null;};
const researchStageLabel=(signal:ResearchSectorSignal|null|undefined,stance:string|undefined)=>hasLeadingSignal(signal)?'先行研究':stance==='insufficient_data'?'证据待补齐':labelLevel(stance??'insufficient_data');
function title(id:string,data:IndustryDataset){const d=data.definitions.find(d=>d.id===id);return d?`${d.entity??''} ${d.nameZh}`:id;}
function labelLevel(v:string){return (levelLabels as Record<string,string>)[v]??v;}
function useClock(){const [value,setValue]=useState(()=>new Date().toISOString());useEffect(()=>{const timer=setInterval(()=>setValue(new Date().toISOString()),60000);return()=>clearInterval(timer)},[]);return value;}
export default function Industry(){
 const [data,setData]=useState<IndustryDataset>(empty),[research,setResearch]=useState<IndustryResearch|null>(null),[industryVersion,setIndustryVersion]=useState(''),[researchVersion,setResearchVersion]=useState(''),[inputVersions,setInputVersions]=useState({macro:'',policyRates:'',policyDecisions:''}),[researchIssue,setResearchIssue]=useState(''),[recommendationHistory,setRecommendationHistory]=useState<Recommendation[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState(''),[tab,setTab]=useState('overview'),[category,setCategory]=useState('capex'),[search,setSearch]=useState('');const now=useClock(),versionRef=useRef(''),historyVersionRef=useRef(''),researchRequestRef=useRef(0);
 async function refresh(){setLoading(true);try{let version='',nextResearchVersion='';let nextInputVersions={macro:'',policyRates:'',policyDecisions:''};try{const manifest=await fetch(manifestEndpoint(),{cache:'no-store'});if(manifest.ok){const payload=await manifest.json() as {industry?:{version?:string;generatedAt?:string};macro?:{version?:string;generatedAt?:string};policyRates?:{version?:string;generatedAt?:string};policyDecisions?:{version?:string;generatedAt?:string};industryResearch?:{version?:string;generatedAt?:string}};version=payload.industry?.version??payload.industry?.generatedAt??'';nextResearchVersion=payload.industryResearch?.version??payload.industryResearch?.generatedAt??'';nextInputVersions={macro:payload.macro?.version??payload.macro?.generatedAt??'',policyRates:payload.policyRates?.version??payload.policyRates?.generatedAt??'',policyDecisions:payload.policyDecisions?.version??payload.policyDecisions?.generatedAt??''};setResearchVersion(nextResearchVersion);setInputVersions(nextInputVersions);if(version&&version===versionRef.current){setError('');return;}}}catch{}const response=await fetch(versionedEndpoint(industryEndpoint(),version),{cache:'force-cache'});if(!response.ok)throw Error('industry cache unavailable');const payload=await response.json() as IndustryDataset;if(!Array.isArray(payload.definitions)||!payload.series)throw Error('invalid cache');setData(payload);setRecommendationHistory(payload.recommendationHistory??[]);const currentVersion=version||payload.generatedAt||String(Date.now());if(currentVersion!==versionRef.current)setResearch(null);versionRef.current=currentVersion;setIndustryVersion(currentVersion);if(!nextResearchVersion)setResearchVersion(payload.generatedAt||currentVersion);historyVersionRef.current=payload.recommendationHistory?.length?currentVersion:'';setError('')}catch{setError('产业数据缓存暂时无法读取。已有数据仍保留，可稍后检查更新。')}finally{setLoading(false)}}
 useEffect(()=>{const read=()=>{const p=new URLSearchParams(location.search);setTab(tabs.some(t=>t[0]===p.get('industry'))?p.get('industry')!:'overview');if(categories.some(c=>c[0]===p.get('category')))setCategory(p.get('category')!)};const initial=window.setTimeout(()=>{void refresh();read()},0);addEventListener('popstate',read);const timer=setInterval(()=>{if(!document.hidden)void refresh()},300000);const visible=()=>{if(!document.hidden)void refresh()};document.addEventListener('visibilitychange',visible);return()=>{clearTimeout(initial);removeEventListener('popstate',read);clearInterval(timer);document.removeEventListener('visibilitychange',visible)}},[]);
 useEffect(()=>{if(!industryVersion||!researchVersion){setResearch(null);return}const requestId=++researchRequestRef.current;setResearch(null);setResearchIssue('');const matchesCurrentInputs=(next:IndustryResearch)=>next.inputs?.industry?.version===industryVersion&&(!inputVersions.macro||next.inputs?.macro?.version===inputVersions.macro)&&(!inputVersions.policyRates||next.inputs?.policyRates?.version===inputVersions.policyRates)&&(!inputVersions.policyDecisions||next.inputs?.policyDecisions?.version===inputVersions.policyDecisions);void fetch(versionedEndpoint(industryResearchEndpoint(),researchVersion),{cache:'force-cache'}).then((response):Promise<IndustryResearch>=>{if(!response.ok)throw Error('research cache unavailable');return response.json() as Promise<IndustryResearch>}).then(next=>{if(requestId!==researchRequestRef.current)return;if(!matchesCurrentInputs(next)){setResearchIssue('研究结论正在等待与当前产业、宏观和政策数据版本一致的更新。');return}if(next.model&&next.analysis)setResearch(next);else setResearchIssue('产业研究缓存暂时不可用，仍可查看下方透明规则。')}).catch(()=>{if(requestId===researchRequestRef.current){setResearch(null);setResearchIssue('产业研究缓存暂时无法读取，仍可查看下方透明规则。')}})},[industryVersion,researchVersion,inputVersions.macro,inputVersions.policyRates,inputVersions.policyDecisions]);
 useEffect(()=>{if(tab!=='conclusions'||!data.generatedAt||historyVersionRef.current===versionRef.current)return;void fetch(versionedEndpoint(industryHistoryEndpoint(),versionRef.current),{cache:'force-cache'}).then(r=>r.ok?r.json():[]).then(next=>{if(Array.isArray(next)){setRecommendationHistory(next as Recommendation[]);historyVersionRef.current=versionRef.current}}).catch(()=>{})},[tab,data.generatedAt]);
 const recommendations=data.recommendations??[];
 function navigate(next:string,cat?:string,id?:string){setTab(next);if(cat)setCategory(cat);const p=new URLSearchParams(location.search);p.set('page','impact');p.set('industry',next);if(cat)p.set('category',cat);history.pushState({},'',appBase()+'?'+p.toString()+(id?'#'+id:''));if(id){setSearch('');setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'}),150)}else window.scrollTo({top:0,behavior:'smooth'})}
 function showMetric(id:string){const def=data.definitions.find(d=>d.id===id);if(def)navigate('metrics',def.category,id)}
 const connected=data.definitions.filter(d=>data.series[d.id]?.observations.some(p=>p.value!=null)).length;
 return <section className="industry-module" aria-label="AI产业链关键指标">
  <div className="industry-toolbar"><div><span className="industry-live"/><strong>{connected}</strong> 已接入指标 <span className="industry-separator">/</span> {data.definitions.length} 项指标目录 <span className="industry-separator">/</span> <span>后台检查 {data.generatedAt?displayTime(data.generatedAt):'尚未取得缓存'}</span></div><button className="industry-button" onClick={()=>void refresh()} disabled={loading}><RefreshCw size={14} className={loading?'spinning':''}/>{loading?'检查中':'检查产业数据'}</button></div>
  <nav className="industry-tabs" aria-label="产业模块导航">{tabs.map(([id,label])=><button key={id} aria-current={tab===id?'page':undefined} className={tab===id?'selected':''} onClick={()=>navigate(id)}>{label}</button>)}</nav>
  {error&&<div className="industry-alert" role="alert"><TriangleAlert size={17}/>{error}</div>}
  {!data.generatedAt&&!error?<div className="industry-empty">正在读取产业数据与来源记录…</div>:<>
  {tab==='overview'&&<Overview data={data} research={research} recommendations={recommendations} now={now} navigate={navigate} showMetric={showMetric}/>}
  {tab==='metrics'&&<><div className="industry-controls"><label>产业环节<select value={category} onChange={e=>navigate('metrics',e.target.value)}>{categories.map(([id,n])=><option key={id} value={id}>{n}</option>)}</select></label><label className="industry-search">搜索公司或指标<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="如 Microsoft、资本开支、铜"/></label></div>{category==='capex'&&<CompanyComparison data={data} capexOnly/>}{category==='projects'&&<ProjectPanel data={data}/>}{category==='costs'&&<CostComparison data={data}/>}
   <div className="industry-chart-grid">{data.definitions.filter(d=>d.category===category&&`${d.nameZh} ${d.entity} ${d.nameEn}`.toLowerCase().includes(search.toLowerCase())).map(d=><MetricCard key={d.id} def={d} data={data} now={now} recommendations={recommendations}/>)}</div>
   {!data.definitions.some(d=>d.category===category)&&<div className="industry-empty">该环节尚未接入可验证指标。</div>}</>}
  {tab==='companies'&&<CompanyComparison data={data}/>}
  {tab==='conclusions'&&<><ResearchConclusionPanelV2 research={research} issue={researchIssue} data={data} showMetric={showMetric}/><details className="industry-panel"><summary>查看底层方向规则与历史</summary><p className="industry-small">以下规则描述已接入数据的方向，未检查连续历史。正式研究结论以本页上方因子模型为准。</p><div className="industry-recommendation-grid">{recommendations.map(r=><RecommendationCard key={r.targetId} recommendation={r} data={data} showMetric={showMetric}/>)}</div><History history={recommendationHistory}/></details></>}
  {tab==='sources'&&<><FinancialUpdates data={data}/><InstitutionalSources data={data} showMetric={showMetric}/><Sources data={data} now={now}/></>}
  </>}
 </section>
}
