function transmission(d:MetricDefinition){if(d.family==='capex')return '资本投入变化可能传导至机房、服务器和芯片采购；公司总资本开支不等于纯AI投入，需核对项目建设和收入兑现。';if(d.category==='costs'||d.family==='electricity')return '价格变化可能改变材料或运营成本，也可能反映供给、天气和需求变化；不同产业环节的影响方向不同。';if(d.category==='cloud')return '云业务收入和利润用于检验前期投入是否兑现；不同公司的业务边界、租赁和订单定义需要分别核对。';return '收入、订单和库存的共同变化可提供产业需求线索，仍需核对交付、毛利率和客户集中度。'}
function CompanyComparison({data,capexOnly=false}:{data:IndustryDataset;capexOnly?:boolean}){
 const [family,setFamily]=useState('capex'),[mode,setMode]=useState('value'),[selected,setSelected]=useState(['MSFT','GOOG','AMZN','META','ORCL']),[range,setRange]=useState('all');const families=[['capex','资本开支'],['capex_ratio','资本开支/收入'],['cloud_revenue','云业务收入'],['cloud_margin','云业务利润率'],['cloud_growth','Azure披露增速'],['datacenter_revenue','数据中心业务收入'],['backlog','订单余额'],['inventory','库存'],['gross_margin','毛利率'],['operating_cash_flow','营业现金流'],['free_cash_flow','自由现金流']];
 const defs=data.definitions.filter(d=>d.family===family&&d.frequency==='quarterly');const entities=[...new Set(defs.map(d=>d.entity).filter(Boolean))] as string[];const chosen=defs.filter(d=>selected.includes(d.entity!));const units=[...new Set(chosen.map(d=>d.unit))];
 const rows=useMemo(()=>{const converted=chosen.map(d=>chartRows(d,data.series[d.id]?.observations??[],{mode:mode==='yoy'?'yoy':mode==='qoq'?'qoq':'value',range}));const quarters=new Set<string>();const maps=converted.map((obs:any[])=>new Map(obs.map(p=>{const q=p.periodEnd.slice(0,4)+'Q'+Math.ceil(Number(p.periodEnd.slice(5,7))/3);quarters.add(q);return [q,p]})));const common=[...quarters].sort().find(q=>maps.every(m=>m.get(q)?.value!=null&&m.get(q).value>0));return [...quarters].sort().map(q=>({quarter:q,...Object.fromEntries(chosen.flatMap((d,i)=>{const p=maps[i].get(q);let v=p?.value??null;if(mode==='normalized')v=common&&q>=common&&v!=null?v/maps[i].get(common).value*100:null;return [[d.id,v],[d.id+'_period',p?.periodStart+' → '+p?.periodEnd],[d.id+'_fiscal',p?.fiscalPeriod]]}))}))},[data,chosen.map(d=>d.id).join(','),mode,range]);
 const canSum=family==='capex'&&mode==='value'&&chosen.length===5&&selected.length===5&&['MSFT','GOOG','AMZN','META','ORCL'].every(e=>selected.includes(e));const sumRows=canSum?rows.filter(r=>chosen.every(d=>(r as any)[d.id]!=null)):[];
 return <section className="industry-panel industry-company-panel"><div className="industry-section-title"><div><h2>{capexOnly?'五家云厂商资本开支':'公司对比'}</h2><p>按公司报告期末所在自然季度定位，保留实际起止日期。不是严格同期排名。</p></div><span className="industry-tag">原始币种 · 无汇率换算</span></div><div className="industry-controls"><label>对比指标<select value={family} onChange={e=>{setFamily(e.target.value);setRange('all');setSelected([...new Set(data.definitions.filter(d=>d.family===e.target.value&&d.entity).map(d=>d.entity!))])}}>{families.filter(([id])=>!capexOnly||['capex','capex_ratio','operating_cash_flow'].includes(id)).map(([id,n])=><option key={id} value={id}>{n}</option>)}</select></label><label>显示口径<select value={mode} onChange={e=>setMode(e.target.value)}><option value="value">原始数值</option><option value="yoy">同比变化</option><option value="qoq">环比变化</option><option value="normalized">共同起始报告季度＝100</option></select></label><label>时间范围<select value={range} onChange={e=>setRange(e.target.value)}><option value="all">全部可用</option>{[1,3,5].map(year=><option key={year} value={String(year)} disabled={!chosen.length||chosen.some(d=>{const pts=data.series[d.id]?.observations??[];return pts.length<2||(Date.parse(pts.at(-1)!.periodEnd)-Date.parse(pts[0].periodEnd))/86400000<year*365})}>近{year}年</option>)}</select></label></div><div className="industry-company-selector">{entities.map(e=><label key={e}><input type="checkbox" checked={selected.includes(e)} onChange={()=>setSelected(s=>s.includes(e)?s.filter(x=>x!==e):[...s,e])}/><i style={{background:companyColor(e)}}/>{e}</label>)}</div><div className="industry-alert subdued"><ShieldCheck size={17}/><span>现金购置固定资产与融资租赁分别看。{family==='cloud_revenue'?'Microsoft Intelligent Cloud 不是 Azure 单项收入；Oracle IaaS+SaaS、AWS、Google Cloud 业务边界不同。':'财年季度与自然季度不等同，鼠标悬停可查看每家公司的实际报告期。'}{chosen.some(d=>!d.isComparableAcrossEntities)&&' 所选指标存在口径差异，不做简单排名。'}</span></div>
 {units.length>1?<div className="industry-empty">所选指标单位不同，请分别查看，不能合并同一数值轴。</div>:<div className="industry-comparison-chart"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={rows} margin={{left:0,right:15,top:15}}><CartesianGrid vertical={false} stroke="#e5ede9" strokeDasharray="3 4"/><XAxis dataKey="quarter" tick={{fontSize:11}}/><YAxis tick={{fontSize:10}} width={55}/><Tooltip content={({active,payload,label})=>active&&payload?.length?<div className="industry-tooltip"><strong>{label} · 期末落点</strong>{payload.map((p:any)=><p key={p.dataKey}>{p.name}: {format(p.value)}<small>{p.payload[p.dataKey+'_fiscal']} · {p.payload[p.dataKey+'_period']}</small></p>)}</div>:null}/>{chosen.map(d=>mode==='value'?<Bar key={d.id} dataKey={d.id} name={d.entity} fill={companyColor(d.entity??'')} maxBarSize={26} isAnimationActive={false}/>:<Line key={d.id} dataKey={d.id} name={d.entity} stroke={companyColor(d.entity??'')} dot connectNulls={false} isAnimationActive={false}/>)}</ComposedChart></ResponsiveContainer></div>}
 <p className="industry-small">纵轴单位：{mode==='normalized'?'起点=100':mode==='value'?units[0]??'—':units[0]==='%'?'个百分点':'%'}。缺失观测留空，不用增速与绝对金额相加。{mode==='normalized'&&' 仅从所有已选公司都有正值的共同报告季度开始；财季起止仍可能不一致。'}</p>
 {canSum&&<details><summary>五家公司资本开支合计（报告期末季度归组，非严格同期总额）</summary><p className="industry-small">仅在五家公司都有数据时汇总。Oracle 财季偏移，租赁口径仍需分别查阅；合计不代表纯AI资本开支。</p>{sumRows.length?<div className="industry-comparison-chart"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={sumRows}><XAxis dataKey="quarter"/><YAxis/><Tooltip/>{chosen.map(d=><Bar key={d.id} dataKey={d.id} name={d.entity} stackId="capex" fill={companyColor(d.entity??'')}/>)}</ComposedChart></ResponsiveContainer></div>:<p>尚无五家公司同时齐备的报告季度，暂不计算合计。</p>}</details>}
 <div className="industry-table-wrap"><table><thead><tr><th>公司</th><th>实际报告期间</th><th>财年季度</th><th>最新值</th><th>来源与口径</th></tr></thead><tbody>{chosen.map(d=>{const p=data.series[d.id]?.observations.at(-1);return <tr key={d.id}><td>{d.entity}</td><td>{p?.periodStart??'—'} → {p?.periodEnd??'—'}</td><td>{p?.fiscalPeriod??'—'}</td><td>{format(p?.value)} {d.unit}</td><td><a href={p?.sourceUrl??d.sourceUrl} target="_blank" rel="noreferrer">{d.nameZh} ↗</a><small>{p?.basis??d.methodology}</small></td></tr>})}</tbody></table></div><p className="industry-company-disclaimer">本页用于观察公司经营与产业环境。尚未完整纳入股价、估值、市场一致预期、资产负债风险和重大事件，因此不生成任何公司的买入或卖出建议。</p></section>
}
function CostComparison({data}:{data:IndustryDataset}){const defs=data.definitions.filter(d=>['WB.copper','WB.aluminum','WB.natural_gas','EIA.VA.commercial'].includes(d.id));const maps=defs.map(d=>new Map((data.series[d.id]?.observations??[]).map(p=>[p.periodEnd.slice(0,7),p.value])));const months=[...new Set(maps.flatMap(m=>[...m.keys()]))].sort().filter(date=>maps.every(m=>m.get(date)!=null&&m.get(date)!>0));const chosen=months.slice(-37);const rows=chosen.map(date=>({date,...Object.fromEntries(defs.map((d,i)=>[d.id,maps[i].get(date)!/maps[i].get(chosen[0])!*100]))}));return <section className="industry-panel"><h3>上游成本对比 · 共同起点＝100</h3><p className="industry-small">统一月度频率 · 仅共同月份 · 不混合美元/公吨、美元/MMBtu与美分/kWh原始坐标轴</p><div className="industry-comparison-chart"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={rows}><XAxis dataKey="date" tick={{fontSize:10}} minTickGap={45}/><YAxis tick={{fontSize:10}}/><Tooltip/><ReferenceLine y={100} stroke="#b7c9c1"/>{defs.map((d,i)=><Line key={d.id} dataKey={d.id} name={d.nameZh} stroke={color[i]} dot={false}/>)}</ComposedChart></ResponsiveContainer></div><div className="industry-table-wrap"><table><thead><tr><th>指标</th><th>原始价格</th><th>1个月</th><th>3个月</th><th>12个月/同比</th></tr></thead><tbody>{defs.map(d=>{const obs=data.series[d.id]?.observations??[];const last=obs.at(-1);const change=(months:number)=>{if(!last)return null;const dt=new Date(last.periodEnd);dt.setUTCDate(1);dt.setUTCMonth(dt.getUTCMonth()-months);const p=obs.find(p=>p.periodEnd.slice(0,7)===dt.toISOString().slice(0,7));return p?.value&&last.value!=null?(last.value/p.value-1)*100:null};return <tr key={d.id}><td>{d.nameZh}</td><td>{format(last?.value)} {d.unit}</td><td>{pct(change(1))}</td><td>{pct(change(3))}</td><td>{pct(change(12))}</td></tr>})}</tbody></table></div></section>}
const projectStatusLabel:Record<string,string>={announced:'已公告',planning:'规划/谈判',approval:'审批',construction:'在建（公告口径）',partially_operational:'部分投运',operational:'已投运',delayed:'延期',cancelled:'取消',unknown:'未知'};
const projectStateCode=(project:{stateCode?:string;region?:string})=>project.stateCode||({Ohio:'OH','South Carolina':'SC',Idaho:'ID',Indiana:'IN',Louisiana:'LA',Texas:'TX',Virginia:'VA',Georgia:'GA',Arizona:'AZ'}[project.region??'']);
const capacityKindLabel:Record<string,string>={compute_capacity:'计算容量',data_center_planned_capacity:'数据中心规划容量',operational_data_center_capacity:'已投运数据中心容量',grid_interconnection_capacity:'并网容量',onsite_generation_capacity:'现场发电容量',unspecified_project_capacity:'项目披露容量（未细分口径）'};
const capacityDisclosure=(item:{powerCapacityMw?:number;capacityMw?:number;capacityKind?:string})=>{const value=item.powerCapacityMw??item.capacityMw;return typeof value==='number'?value.toLocaleString()+' MW · '+(capacityKindLabel[item.capacityKind??'unspecified_project_capacity']??'项目披露容量（未细分口径）'):'未披露';};
const projectSourceState=(project:{sourceUrls:string[]},data:IndustryDataset)=>{const sources=(data.sources??[]).filter(source=>project.sourceUrls.includes(source.url));if(sources.some(source=>source.status==='ready'))return {state:'ready',label:'本轮已核验'};if(sources.some(source=>source.status==='fetch_failed'))return {state:'cached',label:'来源本轮获取失败，展示历史记录'};return {state:'historical',label:'历史项目记录（本轮未核验）'};};
const eventSourceState=(sourceUrl:string|undefined,data:IndustryDataset)=>{const source=(data.sources??[]).find(item=>item.url===sourceUrl);return source?.status==='ready'?{state:'ready',label:'本轮已核验'}:source?.status==='fetch_failed'?{state:'cached',label:'来源本轮获取失败，展示历史记录'}:{state:'historical',label:'历史事件记录（本轮未核验）'};};
const capacitySummary=(items:{powerCapacityMw?:number;capacityMw?:number;capacityKind?:string}[])=>{const values=items.flatMap(item=>{const value=item.powerCapacityMw??item.capacityMw;return typeof value==='number'?[{value,kind:item.capacityKind??'unspecified_project_capacity'}]:[]});if(!values.length)return {headline:'未披露',detail:'当前样本没有可核验的MW披露。'};const kinds=new Set(values.map(item=>item.kind));if(kinds.size!==1)return {headline:'口径不同',detail:'不同类型的MW按项目展示，不合并为单一总数。'};const kind=[...kinds][0];return {headline:values.reduce((sum,item)=>sum+item.value,0).toLocaleString()+' MW',detail:'同口径样本合计 · '+(capacityKindLabel[kind]??'项目披露容量（未细分口径）')+'。'};};
function ProjectPulse({data,compact=false}:{data:IndustryDataset;compact?:boolean}){
 const events=data.projects.flatMap(project=>{const history=project.statusHistory?.length?project.statusHistory:project.announcedAt?[{date:project.announcedAt,status:project.status,sourceUrl:project.sourceUrls[0],capacityMw:project.powerCapacityMw,capacityKind:project.capacityKind,note:'仅有首次公告日期，尚未形成完整生命周期记录。'}]:[];return history.map(event=>({...event,projectId:project.id,projectName:project.name}))}).filter(event=>/^\d{4}-\d{2}-\d{2}$/.test(event.date)).sort((a,b)=>b.date.localeCompare(a.date));
 const cutoff=new Date();cutoff.setUTCDate(cutoff.getUTCDate()-90);
 const recent=events.filter(event=>Date.parse(event.date+'T00:00:00Z')>=cutoff.getTime()&&eventSourceState(event.sourceUrl,data).state==='ready');
 const currentProjects=data.projects.filter(project=>projectSourceState(project,data).state==='ready');
 const construction=currentProjects.filter(project=>project.status==='construction'&&typeof project.powerCapacityMw==='number');
 const planning=currentProjects.filter(project=>['announced','planning','approval'].includes(project.status)&&typeof project.powerCapacityMw==='number');
 const recentCapacity=capacitySummary(recent);
 const constructionCapacity=capacitySummary(construction);
 const planningCapacity=capacitySummary(planning);
 if(compact)return <section className="industry-panel project-pulse"><h3>建设进度快照</h3><p><strong>{constructionCapacity.headline}</strong> 已核验在建项目样本</p><small>{constructionCapacity.detail} 近90日官方状态更新 {recent.length||'暂无'} 项；样本不代表全量市场。</small></section>;
 return <section className="industry-panel project-pulse"><div className="industry-section-title"><div><h3>建设速度与生命周期</h3><p>只统计项目级官方公告中的状态更新；不同容量口径按项目保留，未覆盖全量市场时不把“未检出”解释为零。</p></div><span className="industry-tag">最近 90 日</span></div><div className="project-pulse-grid"><article><span>本轮已核验状态更新</span><strong>{recent.length||'未检出'}</strong><small>{recent.length?recent.map(event=>event.projectName).join('、'):'当前已接入样本没有落入近90日且本轮核验通过的状态事件。'}</small></article><article><span>更新涉及容量</span><strong>{recentCapacity.headline}</strong><small>{recentCapacity.detail} 不代表新增在建或新增投运。</small></article><article><span>当前在建样本</span><strong>{constructionCapacity.headline}</strong><small>{construction.length} 个本轮已核验且披露容量的在建项目。{constructionCapacity.detail}</small></article><article><span>规划/审批样本</span><strong>{planningCapacity.headline}</strong><small>{planning.length} 个本轮已核验且披露容量的项目；不计入在建项目样本。{planningCapacity.detail}</small></article></div>{events.length?<details><summary>项目生命周期事件（{events.length}）</summary><div className="industry-table-wrap"><table><thead><tr><th>日期</th><th>项目</th><th>状态</th><th>披露容量 / 口径</th><th>官方来源 / 新鲜度</th></tr></thead><tbody>{events.map(event=>{const sourceState=eventSourceState(event.sourceUrl,data);return <tr key={event.projectId+'-'+event.date+'-'+event.status}><td>{event.date}</td><td>{event.projectName}<small>{event.note}</small></td><td>{projectStatusLabel[event.status]??event.status}</td><td>{capacityDisclosure(event)}</td><td><a href={event.sourceUrl} target="_blank" rel="noreferrer">公告 ↗</a><small>{sourceState.label}</small></td></tr>})}</tbody></table></div></details>:null}</section>
}
const projectMapPositions:Record<string,{x:number;y:number}>={ID:{x:25,y:30},TX:{x:47,y:70},LA:{x:62,y:72},IN:{x:65,y:43},OH:{x:70,y:39},SC:{x:77,y:57},VA:{x:76,y:49},GA:{x:73,y:61},AZ:{x:35,y:58}};
const projectStateNames:Record<string,string>={ID:'爱达荷州',TX:'得克萨斯州',LA:'路易斯安那州',IN:'印第安纳州',OH:'俄亥俄州',SC:'南卡罗来纳州',VA:'弗吉尼亚州',GA:'佐治亚州',AZ:'亚利桑那州'};
const projectStatusTone:Record<string,string>={construction:'construction',planning:'planning',approval:'planning',announced:'announced',partially_operational:'operational',operational:'operational',delayed:'delayed',cancelled:'delayed',unknown:'announced'};
function ProjectRegionMap({data}:{data:IndustryDataset}){
 const [selected,setSelected]=useState<string|null>(null);
 const regions=[...new Map(data.projects.map(project=>[projectStateCode(project),project])).entries()].filter(([code])=>!!code).map(([code,project])=>{const projects=data.projects.filter(item=>projectStateCode(item)===code);const definition=data.definitions.find(item=>item.id===`EIA.${code}.industrial`);const series=definition?data.series[definition.id]:undefined;return {code:code!,projects,definition,series,latest:series?.observations.at(-1),position:projectMapPositions[code!]}}).sort((a,b)=>a.code.localeCompare(b.code));
 const selectedCode=selected??regions[0].code;
 const active=regions.find(region=>region.code===selectedCode)??regions[0];
 if(!regions.length)return null;
 return <section className="industry-panel project-region-map"><div className="industry-section-title"><div><h3><MapPin size={17}/> 项目区域与电力背景</h3><p>按项目披露的州级地区定位；点击圆点或州卡查看项目状态和 EIA 工业电价背景。</p></div><span className="industry-tag">区域示意图</span></div><div className="project-map-layout"><div className="project-map-frame"><svg viewBox="0 0 100 90" role="img" aria-label="美国项目州级区域示意图"><path className="project-map-outline" d="M12 33 L24 25 L38 28 L48 31 L60 28 L73 34 L88 43 L83 58 L76 65 L66 63 L56 76 L42 72 L33 64 L25 56 L17 49 Z"/>{regions.map(region=>region.position?<g key={region.code} className={`project-map-point ${selectedCode===region.code?'selected':''}`} role="button" tabIndex={0} aria-label={`${projectStateNames[region.code]??region.code}，${region.projects.length}个项目`} onClick={()=>setSelected(region.code)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();setSelected(region.code)}}}><circle cx={region.position.x} cy={region.position.y} r="4.5" className={projectStatusTone[region.projects[0].status]}/><text x={region.position.x} y={region.position.y+1}>{region.code}</text></g>:null)}</svg><small>示意位置，不代表园区精确坐标或并网位置。</small></div><div className="project-region-list" aria-label="项目州列表">{regions.map(region=><button key={region.code} className={selectedCode===region.code?'selected':''} onClick={()=>setSelected(region.code)}><span className={`project-region-dot ${projectStatusTone[region.projects[0].status]}`}/><strong>{region.code} · {projectStateNames[region.code]??region.projects[0].region}</strong><small>{region.projects.length} 项 · {projectStatusLabel[region.projects[0].status]}</small></button>)}</div><article className="project-region-detail" aria-live="polite"><span>{active.code} · {projectStateNames[active.code]??active.projects[0].region}</span><h4>{active.projects.map(project=>project.name).join('、')}</h4><p><b>{projectStatusLabel[active.projects[0].status]}</b> · 披露容量 {active.projects.map(project=>project.powerCapacityMw==null?'未披露':`${project.powerCapacityMw.toLocaleString()} MW`).join('、')}</p><dl><div><dt>工业平均电价</dt><dd>{active.latest?.value==null?'未发布':`${format(active.latest.value)} ${active.definition?.unit??''}`}</dd></div><div><dt>观测期</dt><dd>{active.latest?.periodEnd??'尚无观测'}</dd></div><div><dt>数据状态</dt><dd>{statusText(active.series)}</dd></div></dl>{active.definition&&<a href={active.definition.sourceUrl} target="_blank" rel="noreferrer">{active.definition.sourceName} ↗</a>}<small>州级工业平均零售电价只是成本背景，不是数据中心合同价，也不能单独证明并网或供电可得性。</small></article></div></section>
}
function ProjectPowerContext({data}:{data:IndustryDataset}){const rows=[...new Map(data.projects.map(project=>[projectStateCode(project),project])).entries()].filter(([code])=>!!code).map(([code,project])=>{const definition=data.definitions.find(item=>item.id===`EIA.${code}.industrial`);const series=definition?data.series[definition.id]:undefined;const latest=series?.observations.at(-1);return {code,project,definition,series,latest}});return <section className="industry-panel"><h3>项目所在地的电力背景</h3><p>使用 EIA 州级工业平均零售电价作为区域背景，不是数据中心实际合同价，也不能单独说明并网或供电可得性。</p><div className="industry-table-wrap"><table><thead><tr><th>州 / 关联项目</th><th>工业平均电价</th><th>观测期</th><th>数据状态</th></tr></thead><tbody>{rows.map(({code,project,definition,series,latest})=><tr key={code}><td>{code} · {project.region}<small>{project.name}</small></td><td>{latest?.value==null?'未发布':`${format(latest.value)} ${definition?.unit??''}`}</td><td>{latest?.periodEnd??'尚无观测'}</td><td>{statusText(series)}{definition&&<small><a href={definition.sourceUrl} target="_blank" rel="noreferrer">{definition.sourceName} ↗</a></small>}</td></tr>)}</tbody></table></div></section>}
function ProjectPanel({data}:{data:IndustryDataset}){const progress=['PROJECT.construction_capacity','PROJECT.operational_capacity'].map(id=>({definition:data.definitions.find(d=>d.id===id),series:data.series[id]}));return <section className="industry-panel"><h3>公开数据中心项目登记</h3><p>官方DOE与项目级公告核验样本，按项目唯一ID去重。建设容量只统计明确标为在建且披露容量的项目；投运容量没有官方观测时显示“暂无已发布观测”，不填零。样本不代表美国或全球全量，也不能单独推出个股买卖结论。</p><div className="industry-two-col">{progress.map(({definition,series})=>{const latest=series?.observations?.at(-1);return <article className="industry-mini-card" key={definition?.id}><strong>{definition?.nameZh}</strong><b>{latest?.value==null?'—':`${latest.value.toLocaleString()} ${definition?.unit??''}`}</b><small>{statusText(series)} · {series?.note??'等待来源检查'}</small></article>})}</div><ProjectPulse data={data}/>{data.projects.length?<><ProjectRegionMap data={data}/><div className="industry-table-wrap"><table><thead><tr><th>项目 / 主体</th><th>地区</th><th>状态</th><th>规划容量 MW</th><th>预计投运</th><th>来源 / 核验</th></tr></thead><tbody>{data.projects.map(p=><tr key={p.id}><td>{p.name}<small>{p.owner}</small><small>{p.notes}</small></td><td>{p.country} {p.region}</td><td>{projectStatusLabel[p.status]}</td><td>{p.powerCapacityMw??'未披露'}</td><td>{p.expectedOperationalAt??'未披露'}</td><td>{p.sourceUrls.map(u=><a key={u} href={u} target="_blank" rel="noreferrer">官方来源 ↗ </a>)}<small>{displayTime(p.lastVerifiedAt)}</small></td></tr>)}</tbody></table></div><ProjectPowerContext data={data}/></>:<div className="industry-empty"><Building2 size={29}/><strong>项目数据库待接入</strong><p>尚无经过完整去重、状态和容量核验的公开项目样本。各地区均为数据不足，不显示零。</p></div>}{data.sources?.length?<div className="industry-source-status"><strong>来源检查</strong>{data.sources.map(source=><p key={source.id}><a href={source.url} target="_blank" rel="noreferrer">{source.name} ↗</a> · {statusLabels[source.status]??source.status}{source.error?` · ${source.error}`:''}</p>)}</div>:null}</section>}
function History({history:source}:{history:Recommendation[]}){const history=[...source].sort((a,b)=>b.generatedAt.localeCompare(a.generatedAt)).slice(0,10);return <section className="industry-panel"><h3>建议版本与变化原因</h3><p className="industry-small">从本模块首次运行开始保存；不回填假设性的历史评级。</p>{history.length?<div className="industry-table-wrap"><table><thead><tr><th>生成时间</th><th>产业环节</th><th>建议变化</th><th>原因与规则</th></tr></thead><tbody>{history.map(r=><tr key={r.id+'-'+r.generatedAt}><td>{displayTime(r.generatedAt)}</td><td>{r.targetName}</td><td>{r.previousLevel?labelLevel(r.previousLevel)+' → ':''}{labelLevel(r.level)}</td><td>{r.changeReason}<small>{r.ruleVersion} · {r.id}</small></td></tr>)}</tbody></table></div>:<p className="industry-muted">建议历史将在打开本页时按需读取。</p>}</section>}
function Sources({data,now}:{data:IndustryDataset;now:string}){const unavailable=data.definitions.filter(def=>!(data.series[def.id]?.observations??[]).some(point=>point.value!=null));const incomplete=data.definitions.map(def=>({def,completeness:historyCompleteness(def,data.series[def.id]?.observations??[])})).filter(item=>item.completeness.missingPeriods.length>0);return <>
 <div className="industry-two-col">
  <section className="industry-panel"><h3>数据、时间与修订</h3><p>报告期末、财年季度、来源发布日期与获取时间分别保存。现金流年度累计值只有在基期匹配时才能差分为单季。</p><p>同比 = 本期/上年同期 − 1；环比 = 本期/上期 − 1。百分比指标的变化以百分点解释。缺基期或非正基期时不计算变化率。</p><p>从首次获取开始记录新修订。首次历史导入代表当前可得数据，不代表过去当时已知数据。</p></section>
  <section className="industry-panel"><h3>数据完整性</h3><p>已接入 {data.definitions.length-unavailable.length} / {data.definitions.length} 个指标；未接入 {unavailable.length} 个。缺失期、来源失败和尚未发布会保留为空，不用零值、插值或上一期数值补齐。</p>{incomplete.length?<ul className="industry-quality-list">{incomplete.slice(0,6).map(({def,completeness})=><li key={def.id}><strong>{def.entity} · {def.nameZh}</strong><span>{completeness.observedPeriods}/{completeness.expectedPeriods} 期；缺 {completeness.missingPeriods.map(period=>period.slice(0,7)).join('、')}</span></li>)}</ul>:<p className="industry-small">当前已接入指标的历史期数连续。</p>}{incomplete.length>6&&<p className="industry-small">另有 {incomplete.length-6} 个指标存在历史空档，详见各图的数据完整度。</p>}</section>
  <section className="industry-panel"><h3>建议规则 {RULE_VERSION}</h3><p>投入、需求、建设、盈利、成本五维分别展示正反证据；同一维度按独立证据组取代表信号，相反信号可以形成中性，不用隐蔽分数相抵。</p><p>各产业环节的必需维度必须齐备，并满足该环节规定的需求公司覆盖数，才会生成正式建议。演示、估计、指引、未核验第三方、过期、无基期或获取失败的数据不参与计算。</p><p>投入、订单、收入、盈利中至少三类指标的同比增速连续两个报告期恶化时降低暴露；两类时谨慎观望。必需维度齐备且至少四维正面、无负面维度时积极配置；至少三维正面时分批关注。</p><p>成本上涨对制造端与上游矿业不是同一含义。本版不凭商品涨价推荐矿业配置，也不把产业建议理解为个股买卖信号。</p></section>
  <section className="industry-panel"><h3>后台更新</h3><p>GitHub Actions 独立于网页约每15分钟检查调度；财报和月度数据源每日检查，失败保留最后成功数据并重试。调度可能延迟。</p><p>MU、ETN、VRT公司整体财务由SEC官方XBRL自动获取；TSMC季度数据从官网业绩文件获取，当前季度结束后21天开始探测，不宣称即时财报。公司财报从官方发布列表自动发现新地址；通过财季、单位和实际数值校验后才进入图表。未知表格格式显示“已发布待采集”，来源失败时保留缓存。CSO季度用电每年集中发布；IEA仅解析固定版本报告的情景值。官方明确公告的下一次发布时间会列出；未提供安排时显示未知。发布列表后台每小时检查，已发布待采集会重试，网页关闭后继续运行。</p><p>数据、建议版本与完整复算档案保存在独立 data-cache 分支。网页刷新只重读后台缓存；Windows采集子进程在后台隐藏运行。</p></section>
  <section className="industry-panel"><h3>使用边界</h3><p>公司总资本开支不是纯AI投入；Intelligent Cloud不等同Azure；Meta广告收入不能与云收入相加；全球半导体统计不等于AI芯片需求。</p><p>全国与州级商业/工业平均电价不是数据中心合同价。SIA/WSTS完整历史、HBM现货/合约价、全球项目全量、实时封装产能等需进一步落实授权。</p><p>产业配置建议不等于收益保证；个股功能仍缺行情、估值、一致预期、财务风险和重大事件的完整联合校验。</p></section>
 </div>
 <section className="industry-panel"><h3>全部指标与来源状态</h3><div className="industry-type-key">{Object.entries(labels).map(([k,v])=><span className="industry-tag" key={k}>{v}</span>)}</div><div className="industry-table-wrap"><table><thead><tr><th>指标 / 来源</th><th>类型 / 口径</th><th>频率 / 单位</th><th>最新期 / 获取时间</th><th>状态 / 许可</th></tr></thead><tbody>{data.definitions.map(d=>{const s=data.series[d.id],st=metricStats(d,s?.observations??[],now);return <tr key={d.id}><td>{d.entity} · {d.nameZh}<small>{d.id}</small><a href={d.sourceUrl} target="_blank" rel="noreferrer">{d.sourceName} ↗</a></td><td>{labels[d.valueType]}<small>{d.methodology}</small></td><td>{freq[d.frequency]} · {d.unit}<small>{d.currency??'无币种转换'}</small></td><td>{st.latest?.periodEnd??'尚无观测'}<small>{displayTime(s?.fetchedAt)}</small></td><td>{statusText(s)}{st.freshness==='stale'?' · 过期':''}<small>{d.exportAllowed?'事实数值CSV可导出':'导出待核验许可'}</small>{s?.note&&<small>{s.note}</small>}{s?.error&&<small>{s.error}</small>}</td></tr>})}</tbody></table></div></section>
 </>}
